SELECT 'gongkao', '劝导倡议', 'kp-xingce-language-reading-intent-advocacy', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "劝导倡议类意图"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "不仅告诉你出问题了，还要呼吁你去解决问题。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“这段文字意在说明……” 文段往往呈现“提出问题 - 分析危害”的结构。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心破题"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "作者的终极意图不是让你知道危害，而是让你【采取对策】！如果选项中有针对该问题的合理“呼吁/做法/对策”，优选对策项！"}]}]}$$ AS jsonb), NULL, '劝导倡议的核心考点与解题技巧。', category_node.id, CAST('["言语理解", "片段阅读", "劝导倡议"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_language_reading_intent_advocacy", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
